  "signal_basis": {
    "component_id": "C047.signal_basis",
    "value": "Missing entries and coverage gaps remain explicit while supported patterns are compared across late and timely bookings.",
    "scope": "The recorded gaps do not establish how missingness is distributed across operating conditions.",
    "provenance": {
      "refs": [
        {
