      "rationale": "These spans specify preserving missing entries, recording missing coverage, and comparing patterns with timely bookings; they assert no measured distribution of missingness."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C047.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
